import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length(), ones = 0;
        for (int i = 0; i < n; i++) if (s.charAt(i) == '1') ones++;
        int zeros = n - ones;
        // p1 / p0: ones and zeros among the first k characters.
        int p1 = 0, p0 = 0, best = n;
        for (int k = 0; k <= n; k++) {
            int a = p1 + (zeros - p0); // 0...01...1
            int b = p0 + (ones - p1); // 1...10...0
            best = Math.min(best, Math.min(a, b));
            if (k < n) {
                if (s.charAt(k) == '1') p1++;
                else p0++;
            }
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s := readToken()
	n, ones := len(s), 0
	for i := 0; i < n; i++ {
		if s[i] == '1' {
			ones++
		}
	}
	zeros := n - ones
	// p1 / p0: ones and zeros among the first k characters.
	p1, p0, best := 0, 0, n
	for k := 0; k <= n; k++ {
		a := p1 + (zeros - p0) // 0...01...1
		b := p0 + (ones - p1)  // 1...10...0
		best = min(best, a, b)
		if k < n {
			if s[k] == '1' {
				p1++
			} else {
				p0++
			}
		}
	}
	fmt.Println(best)
}
